import itertools
import json

def solve_puzzle():
    houses = [0, 1, 2, 3]  # indices for houses 1..4

    names = ["Peter", "Eric", "Alice", "Arnold"]
    educations = ["bachelor", "high school", "associate", "master"]
    musics = ["jazz", "rock", "pop", "classical"]
    colors = ["green", "red", "yellow", "white"]
    flowers = ["lilies", "carnations", "daffodils", "roses"]

    for music_perm in itertools.permutations(musics):
        # Clue 8: Pop music is in the second house.
        if music_perm[1] != "pop":
            continue
        pos_classical = music_perm.index("classical")
        pos_rock = music_perm.index("rock")

        for edu_perm in itertools.permutations(educations):
            # Clue 9: Associate's degree is not in the fourth house.
            if edu_perm[3] == "associate":
                continue

            # Clue 4: The person with a master's degree is directly left of classical.
            pos_master = edu_perm.index("master")
            if pos_master + 1 != pos_classical:
                continue

            # Colors next: enforce red<->rock and red directly left of white
            for color_perm in itertools.permutations(colors):
                # Clue 11: Red is directly left of white.
                pos_red = color_perm.index("red")
                pos_white = color_perm.index("white")
                if pos_red + 1 != pos_white:
                    continue

                # Clue 12: Red is the person who loves rock music (same person).
                if pos_red != pos_rock:
                    continue

                # Clue 14 and 1 combined with 13 enforce bachelor == yellow (since daffodils == yellow and bachelor == daffodils)
                pos_bachelor = edu_perm.index("bachelor")
                pos_yellow = color_perm.index("yellow")
                if pos_bachelor != pos_yellow:
                    continue

                for flower_perm in itertools.permutations(flowers):
                    # Clue 2 and 10: Carnations not in first or fourth.
                    if flower_perm[0] == "carnations" or flower_perm[3] == "carnations":
                        continue

                    # Clue 14: Daffodils == Yellow.
                    pos_daff = flower_perm.index("daffodils")
                    if pos_daff != pos_yellow:
                        continue

                    # Clue 7: Yellow is directly left of Roses.
                    pos_roses = flower_perm.index("roses")
                    if pos_yellow + 1 != pos_roses:
                        continue

                    for name_perm in itertools.permutations(names):
                        # Clue 5: Eric is not in the second house.
                        if name_perm[1] == "Eric":
                            continue
                        # Clue 6: Arnold is not in the third house.
                        if name_perm[2] == "Arnold":
                            continue
                        # Clue 3: Master is Alice.
                        if name_perm[pos_master] != "Alice":
                            continue
                        # Clue 13: Arnold is Yellow.
                        if name_perm[pos_yellow] != "Arnold":
                            continue

                        header = ["House", "Name", "Education", "MusicGenre", "Color", "Flower"]
                        rows = []
                        for i in range(4):
                            rows.append([
                                str(i + 1),
                                name_perm[i],
                                edu_perm[i],
                                music_perm[i],
                                color_perm[i],
                                flower_perm[i]
                            ])
                        return {
                            "solution": {
                                "header": header,
                                "rows": rows
                            }
                        }
    return None

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
